export function normalizePath(pathname = "/") {
  let p = String(pathname).split("?")[0].split("#")[0].toLowerCase();
  if (p.length > 1) p = p.replace(/\/+$/, "");
  return p || "/";
}

export function isNoindexPath(path) {
  if (NOINDEX_EXACT.includes(path)) return true;
  if (NOINDEX_PREFIXES.some((x) => path === x || path.startsWith(x + "/"))) return true;
  return /noindex/i.test(SEO_ROUTES[path]?.robots || "");
}

// Resolve everything the head needs for a pathname.
export function getRouteSeo(pathname) {
  const path = normalizePath(pathname);
  const entry = SEO_ROUTES[path];
  const noindex = isNoindexPath(path);
  return {
    path,
    entry,
    noindex,
    canonical: noindex ? null : SITE_ORIGIN + (entry?.canonical || path),
  };
}

export function isIndexable(path) {
  return !isNoindexPath(path) && Boolean(SEO_ROUTES[path]);
}
